import React from 'react';

import { IonIcon } from '@ionic/react';
import { caretBackCircle, caretForwardCircle } from 'ionicons/icons';

import 'styles/YearSelector.css';

const YearSelector = ({ year, onChange }) => {
	return (
		<div className="yearNavigator">
			<IonIcon icon={caretBackCircle} onClick={() => onChange(year - 1)} />
			<h2 className="bigYearLabel">{year}</h2>
			<IonIcon icon={caretForwardCircle} onClick={() => onChange(year + 1)} />
		</div>
	);
};

export default YearSelector;

import React from 'react';

import 'styles/Calendar.css';

const MonthsName = [
	'January', 'February', 'March', 'April', 'May', 'June',
	'July', 'August', 'September', 'October', 'November', 'December'
];

function daysToWeeks(days) {
	let weeks = [[]];

	let emptyFill = 0;
	for (let i = 0; i < days.length; i++) {
		if (i === 0) {
			let day = days[0].date.getDay() - 1;
			if (day < 0) day = 7 - Math.abs(day);

			emptyFill = day;
			for (let x = 0; x < emptyFill; x++) {
				weeks[0].push([]);
			}
		}

		if (!Array.isArray(weeks[Math.floor((i + emptyFill) / 7)])) {
			weeks[Math.floor((i + emptyFill) / 7)] = [];
		}
		weeks[Math.floor((i + emptyFill) / 7)].push(days[i]);
	}

	return weeks;
}

const Calendar = ({ month, days, displayDate }) => {
	return (
		<div>
			<div className="header">
				<span>{MonthsName[month]}</span>
			</div>
			<div className="dayList">
				<span>Mo</span>
				<span>Tu</span>
				<span>We</span>
				<span>Th</span>
				<span>Fr</span>
				<span>Sa</span>
				<span>Su</span>
			</div>
			<div className="weeks">
				{daysToWeeks(days).map(week => (
					<Week>
						{week.map(day => (
							<Day
							date={day.date}
							events={day.events}
							displayDate={displayDate}
							/>
						))}
					</Week>
				))}
			</div>
		</div>
	);
};

const Week = ({ children }) => {
	return <div className="week">{children}</div>;
};

const Day = ({ date, events, displayDate }) => {
	let invisible = date?.getDate() ? '' : ' invisible';
	let intensity = events?.length ?? 0;

	if (intensity > 10) intensity = 10;
	intensity = ` intensity-${intensity}`;

	return <div
		className={"date" + invisible + intensity}
		onClick={() => displayDate(date)}>
			{date?.getDate() || ''}
		</div>
};

export default Calendar;

import React from 'react';

import Calendar from 'components/Calendar';

import allEvents from 'misc/all-events.json';
import 'styles/CalendarGrid.css';

function* DayRange(startDate, endDate) {
	let date = new Date(startDate);
	while (date < endDate) {
		yield new Date(date);
		date.setDate(date.getDate() + 1);
	}
}

export function getEventsOnDate(date) {
	let events = [];
	for (const event of allEvents) {
		if (date >= event.date[0] * 1000 && date <= event.date[1] * 1000) {
			events.push(Object.assign({}, event));
		}
	}

	return events;
}

const CalendarGrid = ({ year, displayDate }) => {
	// Iterate month
	let months = [];
	for (let m = 0; m < 12; m++) {
		let days = [];
		// Iterate days
		let startDate = new Date(year, m);
		let endDate = new Date(year, m + 1);
		for (const dayDate of DayRange(startDate, endDate)) {
			days.push({
				date: dayDate,
				events: getEventsOnDate(dayDate)
			});
		}

		months.push({
			days, displayDate,
			month: m
		});
	}

	return (
		<div className="calendarGrid">
			{months.map(m => <Calendar {...m} />)}
		</div>
	);
};

export default CalendarGrid;

import React from 'react';

import 'styles/SelectedEvents.css';

const SelectedEvents = ({ events, date }) => {
	return (
	<>
		<h3 className="eventDateDisplay">{date.getFullYear()}-{date.getMonth() + 1}-{date.getDate()}</h3>
		<div className="eventsGridDisplay">
			{events?.map(e => <EventDisplay {...e} />)}
		</div>
	</>
	);
}

const EventDisplay = ({ name, hyperlink, location, misc }) => {
	return (
		<div className="eventCell">
			<b>{name}</b>
			<a href={hyperlink}>{hyperlink}</a>
			<span>{location}</span>
			<p dangerouslySetInnerHTML={{__html: misc}}></p>
		</div>
	);
};

export default SelectedEvents;
